mapper.insert:
CREATE TABLE IF NOT EXISTS asset_download_count
(
  format          VARCHAR(100)             NOT NULL,
  asset_id        INT                      NOT NULL,
  repository_id   INT                      NOT NULL,
  component_id    INT,
  download_count  BIGINT                   NOT NULL,
  last_downloaded TIMESTAMP WITH TIME ZONE NOT NULL,

  CONSTRAINT pk_asset_download_count PRIMARY KEY (format, asset_id)
);

CREATE INDEX IF NOT EXISTS idx_asset_download_count_repository ON asset_download_count (format, repository_id);
CREATE INDEX IF NOT EXISTS idx_asset_download_count_component ON asset_download_count (format, component_id);

CREATE TABLE IF NOT EXISTS asset_download_count
(
  format          VARCHAR(100)             NOT NULL,
  asset_id        INT                      NOT NULL,
  repository_id   INT                      NOT NULL,
  component_id    INT,
  download_count  BIGINT                   NOT NULL,
  last_downloaded TIMESTAMP WITH TIME ZONE NOT NULL,

  CONSTRAINT pk_asset_download_count PRIMARY KEY (format, asset_id)
);


DO $$
BEGIN
  IF to_regclass('idx_asset_download_count_repository') IS NULL THEN
    CREATE INDEX idx_asset_download_count_repository ON asset_download_count (format, repository_id);
  END IF;
  IF to_regclass('idx_asset_download_count_component') IS NULL THEN
    CREATE INDEX idx_asset_download_count_component ON asset_download_count (format, component_id);
  END IF;
END
$$;

mapper.select:
SELECT format, asset_id, repository_id, component_id, download_count, last_downloaded
  FROM asset_download_count
 WHERE format = #{format}
   AND asset_id IN
#{assetId};

mapper.delete:
DELETE FROM asset_download_count
 WHERE format = #{format}
   AND asset_id IN
#{assetId};

DELETE FROM asset_download_count
 WHERE format = #{format}
   AND component_id IN
#{componentId};

DELETE FROM asset_download_count
 WHERE format = #{format}
   AND repository_id = #{repositoryId};
